//! `probe`, `gpio`, and `i2c` against a replayed probe (POGO_REPLAY): output shapes,
//! guardrails, and exit codes. The fixtures are generated by pogo-core's
//! `probe_fixtures_are_current` test.

#![allow(clippy::unwrap_used)]

use std::path::PathBuf;

use assert_cmd::Command;
use serde_json::Value;

fn fixture(name: &str) -> String {
    format!(
        "{}/../../tests/fixtures/synthetic/{name}.jsonl",
        env!("CARGO_MANIFEST_DIR")
    )
}

/// A config declaring the docs' example pins, one file per process.
fn config() -> PathBuf {
    let dir = std::env::temp_dir().join(format!("pogo-probe-cli-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("pogo.toml");
    std::fs::write(
        &path,
        "[pins.target_en]\nprobe_pin = 2\nmode = \"open-drain\"\n\
         [pins.led]\nprobe_pin = 10\nmode = \"push-pull\"\n",
    )
    .unwrap();
    path
}

fn pogo(replay: &str, args: &[&str]) -> Command {
    let mut cmd = Command::cargo_bin("pogo").unwrap();
    cmd.env_remove("POGO_FORMAT")
        .env("NO_COLOR", "1")
        .env("POGO_CONFIG", config())
        .env("POGO_REPLAY", fixture(replay))
        .args(args)
        .args(["--wait-lock", "30s"]);
    cmd
}

/// Run with `-f json`, check the exit code, and validate against the committed schema.
fn json(replay: &str, args: &[&str], code: i32) -> Value {
    let out = pogo(replay, args)
        .args(["-f", "json"])
        .assert()
        .code(code)
        .get_output()
        .clone();
    let v: Value = serde_json::from_slice(&out.stdout).unwrap();
    let path = format!(
        "{}/../../schemas/{}.json",
        env!("CARGO_MANIFEST_DIR"),
        v["command"].as_str().unwrap()
    );
    let schema: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let validator = jsonschema::validator_for(&schema).unwrap();
    let errors: Vec<String> = validator.iter_errors(&v).map(|e| e.to_string()).collect();
    assert!(errors.is_empty(), "{args:?}: {errors:#?}\n{v:#}");
    v
}

fn human(replay: &str, args: &[&str]) -> String {
    let out = pogo(replay, args).assert().code(0).get_output().clone();
    String::from_utf8(out.stdout).unwrap()
}

#[test]
fn probe_info_reports_firmware_and_driven_pins() {
    let v = json("probe_info", &["probe", "info"], 0);
    let d = &v["data"];
    assert_eq!(d["fw_version"], "0.1.0");
    assert_eq!(d["protocol_version"], "1.0");
    assert_eq!(d["board"], "rp2040");
    assert_eq!(d["driven_pins"], serde_json::json!([2]));
    insta::assert_snapshot!("probe_info_human", human("probe_info", &["probe", "info"]));
}

#[test]
fn selftest_passes_and_fails_with_check_failed() {
    let v = json("probe_selftest_ok", &["probe", "selftest"], 0);
    let ids: Vec<&str> = v["data"]["checks"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c["id"].as_str().unwrap())
        .collect();
    assert_eq!(ids, ["handshake", "pins_released", "ina226", "i2c_bus0"]);
    let v = json("probe_selftest_bus_stuck", &["probe", "selftest"], 1);
    assert_eq!(v["error"]["code"], "CHECK_FAILED");
    assert_eq!(
        v["data"]["checks"][2]["status"], "warn",
        "no INA226 is a warning"
    );
    assert_eq!(v["data"]["checks"][3]["status"], "fail");
}

#[test]
fn gpio_get_set_pulse() {
    let v = json("probe_level_low", &["gpio", "get", "target_en"], 0);
    assert_eq!(
        (v["data"]["probe_pin"].as_u64(), v["data"]["level"].as_str()),
        (Some(2), Some("low"))
    );
    let v = json("probe_ok", &["gpio", "set", "target_en", "low"], 0);
    assert_eq!(v["data"]["state"], "low");
    let args = [
        "gpio",
        "pulse",
        "led",
        "--level",
        "high",
        "--duration",
        "50ms",
    ];
    let v = json("probe_ok", &args, 0);
    assert_eq!(v["data"]["duration_ms"], 50.0);
    assert_eq!(
        human("probe_ok", &args),
        "pulse led (GP10) high for 50 ms\n"
    );
}

#[test]
fn gpio_guardrails_exit_8_and_dry_run_skips_the_probe() {
    let v = json("probe_silent", &["gpio", "set", "nope", "low"], 8);
    assert!(
        v["error"]["message"]
            .as_str()
            .unwrap()
            .contains("declared: led, target_en")
    );
    let v = json("probe_silent", &["gpio", "set", "target_en", "high"], 8);
    assert!(
        v["error"]["message"]
            .as_str()
            .unwrap()
            .contains("open-drain")
    );
    // The silent probe would time out if it were asked anything.
    let v = json(
        "probe_silent",
        &["gpio", "set", "led", "high", "--dry-run"],
        0,
    );
    assert_eq!(v["data"]["dry_run"], true);
}

#[test]
fn i2c_scan_read_write() {
    let v = json("probe_scan", &["i2c", "scan"], 0);
    assert_eq!(v["data"]["range"], serde_json::json!(["0x08", "0x77"]));
    let found = &v["data"]["found"];
    assert_eq!(found[2]["addr"], "0x76");
    assert_eq!(found[2]["addr_dec"], 118);
    assert_eq!(found[2]["may_be"], serde_json::json!(["BME280", "BMP280"]));
    insta::assert_snapshot!("i2c_scan_human", human("probe_scan", &["i2c", "scan"]));

    let v = json(
        "probe_bytes",
        &["i2c", "read", "0x68", "--reg", "0x75", "--len", "1"],
        0,
    );
    assert_eq!(v["data"]["bytes_hex"], serde_json::json!(["0x68"]));
    assert_eq!(v["data"]["reg"], "0x75");

    let v = json("probe_ok", &["i2c", "write", "0x68", "0x6b", "0x00"], 0);
    assert_eq!(v["data"]["bytes_written"], 2);
    assert_eq!(v["data"]["bytes_hex"], serde_json::json!(["0x6b", "0x00"]));
    let v = json("probe_silent", &["i2c", "write", "0x50", "0x00"], 8);
    assert_eq!(v["error"]["code"], "GUARDRAIL_REFUSED");
}

#[test]
fn probe_failures_have_stable_codes() {
    let v = json("probe_nack", &["i2c", "read", "0x42", "--len", "1"], 6);
    assert_eq!(v["error"]["code"], "DEVICE_IO");
    let v = json("probe_silent", &["probe", "info"], 6);
    assert_eq!(v["error"]["code"], "PROTOCOL");
    let v = json("probe_old_major", &["probe", "info"], 6);
    assert_eq!(v["error"]["code"], "PROTOCOL_MISMATCH");
    assert_eq!(v["error"]["details"]["probe_protocol_major"], 2);
}

#[test]
fn no_probe_connected_is_device_not_found() {
    let out = Command::cargo_bin("pogo")
        .unwrap()
        .env_remove("POGO_REPLAY")
        .env("POGO_CONFIG", config())
        .args(["probe", "info", "-f", "json"])
        .assert()
        .code(3)
        .get_output()
        .clone();
    let v: Value = serde_json::from_slice(&out.stdout).unwrap();
    assert_eq!(v["error"]["code"], "DEVICE_NOT_FOUND");
    assert!(v["error"]["hint"].as_str().unwrap().contains("--probe"));
}
